			events.EventTime:          s.Clock.Now().UTC(),
		})
		c.Assert(err, check.IsNil)
	}

	var history []apievents.AuditEvent

	for i := 0; i < dynamoDBLargeQueryRetries; i++ {
		time.Sleep(s.EventsSuite.QueryDelay)

